class Solution {
public:
    int countStaircase(vector<int>& nums) {
        int n = nums.size();
        int ans = 0;
        for (int l = 0; l < n; l++) {
            unordered_map<int,int> freq, rank;
            int distinct = 0;
            int mismatches = 0;
            for (int r = l; r < n; r++) {
                int v = nums[r];
                auto it = freq.find(v);
                if (it == freq.end()) {
                    distinct++;
                    rank[v] = distinct;
                    freq[v] = 1;
                    if (distinct != 1) mismatches++;
                } else {
                    int oldFreq = it->second;
                    int req = rank[v];
                    int newFreq = oldFreq + 1;
                    if (newFreq > req) break;
                    if (newFreq == req) mismatches--;
                    it->second = newFreq;
                }
                if (mismatches == 0) ans++;
            }
        }
        return ans;
    }
};
